def process(loadAllYears) -> pd.DataFrame:
    import pandas as pd

    df = loadAllYears.copy()

    # normalize column names for robust matching
    norm = {c: c.strip() for c in df.columns}
    df = df.rename(columns=norm)

    # Heuristically determine key columns
    cols_lower = {c: c.lower() for c in df.columns}

    def find_col(keywords, must_all=False):
        hits = []
        for c, cl in cols_lower.items():
            if must_all:
                if all(k in cl for k in keywords):
                    hits.append(c)
            else:
                if any(k in cl for k in keywords):
                    hits.append(c)
        return hits

    # Likely columns
    marine_candidates = find_col(["marine"], must_all=False) + find_col(["water", "type"], must_all=False)
    beach_candidates = find_col(["beach"], must_all=False)
    name_candidates = []
    for kw in [("beach", "name"), ("site", "name"), ("location",), ("waterbody",), ("water body",)]:
        name_candidates += find_col(list(kw), must_all=False)

    # Violation indicator candidates
    viol_candidates = find_col(["violation"], must_all=False) + find_col(["exceed"], must_all=False) + find_col(["advisory"], must_all=False) + find_col(["closure"], must_all=False) + find_col(["posted"], must_all=False)

    # choose best guess columns by preference order
    def pick(preferred_list):
        for c in preferred_list:
            if c in df.columns:
                return c
        return None

    beach_name_col = pick([c for c in df.columns if "beach" in c.lower() and "name" in c.lower()])
    if beach_name_col is None:
        beach_name_col = pick([c for c in df.columns if "beach" in c.lower()])
    if beach_name_col is None:
        beach_name_col = pick([c for c in df.columns if "site" in c.lower() and "name" in c.lower()])
    if beach_name_col is None:
        # last resort: first string-like id
        beach_name_col = df.columns[0]

    water_type_col = pick([c for c in df.columns if "water" in c.lower() and "type" in c.lower()])
    if water_type_col is None:
        water_type_col = pick([c for c in df.columns if "type" in c.lower()])

    violation_col = pick([c for c in df.columns if "violation" in c.lower()])
    if violation_col is None:
        # common phrasing like "Result" "Status" "Advisory" etc.
        violation_col = pick([c for c in df.columns if any(k in c.lower() for k in ["advisory", "closure", "posted", "status", "exceed"])])

    # Filter marine beaches
    marine_df = df
    if water_type_col is not None:
        marine_df = marine_df[marine_df[water_type_col].astype(str).str.contains("marine", case=False, na=False)]
    else:
        # if no water type col, try a broader filter for rows mentioning marine
        marine_df = marine_df[df.apply(lambda r: r.astype(str).str.contains('marine', case=False, na=False).any(), axis=1)]

    # Determine violations: treat as violation if violation_col contains common "bad" indicators or equals True/1
    if violation_col is None:
        # If no explicit violation flag, assume no way to detect violations -> count 0
        out = pd.DataFrame([{ "safeMarineBeachesAllYears": 0, "beachNameCol": beach_name_col, "waterTypeCol": water_type_col, "violationCol": None }])
        return out

    v = marine_df[violation_col]
    # boolean-like
    violation_flag = pd.Series(False, index=marine_df.index)
    if pd.api.types.is_bool_dtype(v):
        violation_flag = v.fillna(False)
    elif pd.api.types.is_numeric_dtype(v):
        violation_flag = v.fillna(0) != 0
    else:
        vs = v.astype(str).str.strip().str.lower()
        bad_tokens = ["violation", "yes", "y", "true", "t", "1", "exceed", "exceeded", "unsafe", "advisory", "posted", "close", "closed", "closure", "do not swim", "warning"]
        good_tokens = ["no", "n", "false", "f", "0", "safe", "ok", "none"]
        violation_flag = vs.apply(lambda s: any(tok in s for tok in bad_tokens) and not any(tok == s for tok in good_tokens))
        # if value exactly 'no violation' etc.
        violation_flag = violation_flag & (~vs.str.contains(r"no\s+violation", na=False))

    marine_df = marine_df.assign(_violation=violation_flag)

    # A beach is safe for entire period if it has no violation records in any year.
    # If missing year, assumed safe => only need to ensure _violation never true.
    beach_viols = marine_df.groupby(beach_name_col, dropna=False)["_violation"].any().reset_index(name="anyViolation")
    safe_count = int((~beach_viols["anyViolation"]).sum())

    out = pd.DataFrame([{ "safeMarineBeachesAllYears": safe_count, "beachNameCol": beach_name_col, "waterTypeCol": water_type_col, "violationCol": violation_col, "marineBeachesObserved": beach_viols.shape[0] }])
    return out
